import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int MAXM = 900000;
    static int n, t;
    static int[] level = new int[MAXN], adj = new int[MAXN], copy_adj = new int[MAXN], fila = new int[MAXN];
    static int[] to = new int[MAXM], ant = new int[MAXM], cap = new int[MAXM];
    static int pa;
    static int S, T;
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, 1, 0, -1};
    static char[][] gr = new char[21][21], gr2 = new char[21][21];
    static int[][] inds = new int[21][21], inds2 = new int[21][21], mk = new int[21][21], c = new int[21][21];
    static int in;
    static Pair[] q = new Pair[MAXN];
    static int rp, cp;

    static class Pair {
        int first, second;
        Pair(int f, int s) {
            first = f;
            second = s;
        }
    }

    static void add_edge(int f, int t, int c) {
        to[pa] = t; cap[pa] = c; ant[pa] = adj[f]; adj[f] = pa++;
        to[pa] = f; cap[pa] = 0; ant[pa] = adj[t]; adj[t] = pa++;
    }

    static boolean valid(int a, int b) {
        return a >= 0 && a < n && b >= 0 && b < n;
    }

    static void perform_bfs(int a, int b) {
        int ini = 0, fim = 0;
        for (int i = 0; i < 21; i++) {
            Arrays.fill(mk[i], 0);
            Arrays.fill(c[i], -1);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gr[i][j] == 'Y') {
                    mk[i][j] = 1;
                }
            }
        }
        q[fim++] = new Pair(rp, cp);
        q[fim++] = new Pair(a, b);
        c[a][b] = c[rp][cp] = 0;
        mk[a][b] = 1;
        mk[rp][cp] = 2;
        while (ini < fim) {
            Pair now = q[ini++];
            int x = now.first, y = now.second;
            if (mk[x][y] == 1 && gr2[x][y] > '0' && gr2[x][y] <= '9') {
                add_edge(inds[a][b], inds2[x][y], 9);
            }
            if (mk[x][y] == 1 && c[x][y] == t) continue;
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (valid(nx, ny) && mk[nx][ny] == 0) {
                    mk[nx][ny] = mk[x][y];
                    c[nx][ny] = c[x][y] + 1;
                    q[fim++] = new Pair(nx, ny);
                } else if (mk[x][y] == 1 && valid(nx, ny) && mk[nx][ny] == 2 && c[nx][ny] == c[x][y] + 1 && gr2[nx][ny] > '0' && gr2[nx][ny] <= '9') {
                    add_edge(inds[a][b], inds2[nx][ny], 9);
                }
            }
        }
    }

    static boolean bfs(int s, int t) {
        int[] dist = new int[MAXN];
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new LinkedList<>();
        dist[s] = 0;
        queue.offer(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int i = adj[u]; i != -1; i = ant[i]) {
                if (cap[i] > 0 && dist[to[i]] < 0) {
                    dist[to[i]] = dist[u] + 1;
                    queue.offer(to[i]);
                }
            }
        }
        return dist[t] >= 0;
    }

    static int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        for (int i = adj[u]; i != -1; i = ant[i]) {
            if (cap[i] > 0 && level[to[i]] < 0) {
                level[to[i]] = level[u] + 1;
                int pushed = dfs(to[i], t, Math.min(flow, cap[i]));
                if (pushed > 0) {
                    cap[i] -= pushed;
                    cap[i ^ 1] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int compute_max_flow(int s, int t) {
        int total_flow = 0;
        while (true) {
            Arrays.fill(level, -1);
            level[s] = 0;
            if (!bfs(s, t)) break;
            for (int i = 0; i < pa; i++) {
                if (cap[i] > 0 && level[to[i]] == level[pa]) {
                    level[to[i]] = level[pa] + 1;
                }
            }
            int pushed;
            while ((pushed = dfs(s, t, Integer.MAX_VALUE)) > 0) {
                total_flow += pushed;
            }
        }
        return total_flow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        S = 202;
        T = 203;
        Arrays.fill(adj, -1);
        pa = 0;
        in = 0;
        for (int i = 0; i < 21; i++) {
            Arrays.fill(inds[i], -1);
            Arrays.fill(inds2[i], -1);
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            gr[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (gr[i][j] > '0' && gr[i][j] <= '9') {
                    add_edge(S, in, gr[i][j] - '0');
                    inds[i][j] = in++;
                }
                if (gr[i][j] == 'Z') {
                    rp = i;
                    cp = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            gr2[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (gr2[i][j] > '0' && gr2[i][j] <= '9') {
                    add_edge(in, T, gr2[i][j] - '0');
                    inds2[i][j] = in++;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gr[i][j] > '0' && gr[i][j] <= '9' && gr2[i][j] > '0' && gr2[i][j] <= '9') {
                    add_edge(inds[i][j], inds2[i][j], 9);
                }
                if (gr[i][j] > '0' && gr[i][j] <= '9') {
                    perform_bfs(i, j);
                }
            }
        }
        System.out.println(compute_max_flow(S, T));
    }
}
